vec2 movingNoise(vec2 coord, float t) {
    vec2 gradient;
    float noise = lpfn_psrdnoise(
        coord + vec2(t * 0.030, -t * 0.020),
        vec2(0.0),
        t * 0.090,
        gradient,
        0u
    );
